    'footer.brandName': 'Mercosur Chamber of Commerce',
    'footer.brandDescription': 'A private, independent, non-profit civil association dedicated to strengthening trade, investment, business cooperation, and economic integration between Latin America and the world.',
    'footer.address': 'Oriental Republic of Uruguay',
