    'footer.brandName': 'Câmara de Comércio Mercosul',
    'footer.brandDescription': 'Associação civil privada, independente e sem fins lucrativos, voltada ao fortalecimento do comércio, do investimento, da cooperação empresarial e da integração econômica entre a América Latina e o mundo.',
